:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
}

/* One translucent ink for every edge: black at 8% in light, white at 10% in dark. */
.hairline {
  border: 1px solid var(--hairline);
  background-color: var(--surface);
  /* Keep the fill out from under the translucent border, so the edge mixes with the page and its shadow, not with the card. */
  background-clip: padding-box;
}

/* Inputs need a slightly stronger edge than cards. */
.hairline-strong {
  border: 1px solid light-dark(oklch(0 0 0 / 0.1), oklch(1 0 0 / 0.14));
  background-clip: padding-box;
}

/* Layout dividers stay real borders. */
.hairline-rule {
  border: 0;
  border-block-start: 1px solid var(--hairline);
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
}

:root {
  /* Layer 1 = the 1px ring. Layer 2 = contact shadow. Layer 3 = ambient depth. Dark mode keeps only a white ring. */
  --shadow-border:
    0 0 0 1px light-dark(oklch(0 0 0 / 0.06), oklch(1 0 0 / 0.08)),
    0 1px 2px -1px light-dark(oklch(0 0 0 / 0.06), transparent),
    0 2px 4px 0 light-dark(oklch(0 0 0 / 0.04), transparent);
  --shadow-border-hover:
    0 0 0 1px light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.13)),
    0 1px 2px -1px light-dark(oklch(0 0 0 / 0.08), transparent),
    0 2px 4px 0 light-dark(oklch(0 0 0 / 0.06), transparent);
}

.card {
  background: var(--surface);
  border-radius: 12px;
  box-shadow: var(--shadow-border);
  transition: box-shadow 150ms ease-out;
}

@media (hover: hover) {
  .card:hover { box-shadow: var(--shadow-border-hover); }
}

/* Forced-colours mode removes box-shadow, so give the edge back. */
@media (forced-colors: active) {
  .card { outline: 1px solid CanvasText; }
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
}

.card-edge {
  background: var(--surface);
  border-radius: 12px;
  box-shadow:
    0 0 0 1px light-dark(rgb(0 0 0 / 0.059), rgb(255 255 255 / 0.173)),  /* ring */
    0 0 0 0.5px light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.15)),        /* half-pixel line sharpens the ring on 2x screens */
    0 1px 1px 0 light-dark(rgb(0 0 0 / 0.024), rgb(0 0 0 / 0.4)),         /* contact */
    0 2px 1px -1px light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.4)),       /* contact, pulled in */
    0 1px 3px 0 light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.3));          /* short ambient */
}

@media (forced-colors: active) {
  .card-edge { outline: 1px solid CanvasText; }
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --accent: oklch(0.53 0.2 262);
}

.gradient-border {
  --_fill: var(--surface);              /* must be opaque */
  --_from: light-dark(oklch(0 0 0 / 0.16), oklch(1 0 0 / 0.24));
  --_to: light-dark(oklch(0 0 0 / 0.05), oklch(1 0 0 / 0.04));
  border: 1px solid transparent;
  border-radius: 14px;
  background:
    linear-gradient(var(--_fill) 0 0) padding-box,
    linear-gradient(to bottom, var(--_from), var(--_to)) border-box;
}

/* Accent version for one emphasised card. */
.gradient-border[data-tone="accent"] {
  --_from: var(--accent);
  --_to: color-mix(in oklch, var(--accent) 12%, transparent);
}

:root {
  color-scheme: light dark;
  --accent: oklch(0.53 0.2 262);
}

.mask-border {
  position: relative;
  border-radius: 14px;
  background: light-dark(oklch(1 0 0 / 0.6), oklch(1 0 0 / 0.04));
}

.mask-border::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;                         /* border thickness */
  border-radius: inherit;
  background: linear-gradient(135deg, var(--accent), transparent 35%, transparent 65%, var(--accent));
  /* Show only the padding ring: content-box layer is cut out of the full layer. */
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
  --accent: oklch(0.53 0.2 262);
  --accent-fg: oklch(0.99 0 0);
}

/* Solid, coloured surface: light line inside the top edge. */
.lit-solid {
  background: var(--accent);
  color: var(--accent-fg);
  border: 1px solid var(--accent);
  box-shadow: inset 0 1px 0 0 oklch(1 0 0 / 0.16);
}
.lit-solid:active {
  box-shadow: inset 0 1px 0 0 oklch(0 0 0 / 0.08);   /* pressed: the highlight turns into a shade */
}

/* Neutral surface: a shadow on a pseudo-element shades the border itself, following the corner radius. */
.lit-edge {
  --_r: 16px;
  position: relative;
  border: 1px solid var(--hairline);
  border-radius: var(--_r);
  background: var(--surface);
  background-clip: padding-box;
}
.lit-edge::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: calc(var(--_r) - 1px);
  pointer-events: none;
  box-shadow:
    0 1px light-dark(oklch(0 0 0 / 0.04), transparent),    /* light mode: bottom edge darker */
    0 -1px light-dark(transparent, oklch(1 0 0 / 0.06));   /* dark mode: top edge lighter */
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
}

.bezel {
  border-radius: 20px;
  background: var(--surface);
  background-clip: padding-box;
  /* Three lines that do not overlap: outline (outside), border (middle), inset shadow (inside). */
  outline: 1px solid light-dark(oklch(1 0 0 / 0.6), oklch(1 0 0 / 0.06));
  outline-offset: 0;
  border: 1px solid light-dark(oklch(0 0 0 / 0.12), oklch(0 0 0 / 0.8));
  box-shadow:
    inset 0 0 0 1px light-dark(oklch(1 0 0 / 0.5), oklch(1 0 0 / 0.07)),
    0 8px 24px -8px light-dark(oklch(0 0 0 / 0.12), oklch(0 0 0 / 0.6));
}

:root { color-scheme: light dark; }

.ghost-border { position: relative; }

.ghost-border::before,
.ghost-border::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid transparent;
  border-radius: inherit;
  pointer-events: none;
}
/* Light scheme: the line can only darken what is under it. */
.ghost-border::before {
  border-color: light-dark(oklch(0.9 0 0), transparent);
  mix-blend-mode: darken;
}
/* Dark scheme: the line can only lighten what is under it. */
.ghost-border::after {
  border-color: light-dark(transparent, oklch(0.32 0 0));
  mix-blend-mode: lighten;
}

:root {
  color-scheme: light dark;
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
}

body { overflow-x: clip; }              /* the rules are wider than the column */

.rule-y { position: relative; }

.rule-y::before,
.rule-y::after {
  content: "";
  position: absolute;
  inset-inline: calc(50% - 50vw);       /* reach both window edges from inside a centred column */
  height: 1px;
  background: var(--hairline);
  pointer-events: none;
}
.rule-y::before { inset-block-start: 0; }
.rule-y::after { inset-block-end: 0; }

/* Optional vertical rails on the column itself. */
.rule-x {
  border-inline: 1px solid var(--hairline);
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
  --accent: oklch(0.53 0.2 262);
}

.beam {
  position: relative;
  border-radius: 16px;
  background: var(--surface);
  box-shadow: 0 0 0 1px var(--hairline);
}

.beam-track {
  position: absolute;
  inset: 0;
  border: 1px solid transparent;        /* beam thickness */
  border-radius: inherit;
  pointer-events: none;
  /* Only the border ring stays visible. */
  mask: linear-gradient(#000 0 0) padding-box exclude, linear-gradient(#000 0 0) border-box;
}

.beam-track > i {
  position: absolute;
  width: 64px;                          /* beam length */
  aspect-ratio: 1;
  background: linear-gradient(to left, var(--accent), transparent);
  offset-path: rect(0 auto auto 0 round 64px);
  offset-distance: 0%;
}

@media (prefers-reduced-motion: no-preference) {
  .beam-track > i { animation: beam-travel 6s linear infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .beam-track > i { display: none; }
}

@keyframes beam-travel {
  to { offset-distance: 100%; }
}

:root {
  color-scheme: light dark;
  /* Light comes from straight above: only y offsets. Negative spread keeps large blurs under the element. */
  --_ring: light-dark(rgb(0 0 0 / 0.059), rgb(255 255 255 / 0.173));

  /* 1: recessed (inputs, wells) */
  --elev-1:
    inset 0 0 0 1px light-dark(rgb(0 0 0 / 0.122), rgb(255 255 255 / 0.106)),
    inset 0 1.5px 2px 0 light-dark(rgb(0 0 0 / 0.124), rgb(0 0 0 / 0.3));

  /* 2: resting card */
  --elev-2:
    0 0 0 1px var(--_ring),
    0 0 0 0.5px light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.15)),
    0 1px 1px 0 light-dark(rgb(0 0 0 / 0.024), rgb(0 0 0 / 0.4)),
    0 2px 1px -1px light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.4)),
    0 1px 3px 0 light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.3));

  /* 3: raised card, hover, dropdown */
  --elev-3:
    0 0 0 1px var(--_ring),
    0 2px 3px -2px light-dark(rgb(0 0 0 / 0.059), rgb(0 0 0 / 0.15)),
    0 3px 12px -4px light-dark(rgb(0 0 0 / 0.1), transparent),
    0 4px 16px -8px light-dark(rgb(0 0 0 / 0.1), transparent),
    0 3px 8px -2px light-dark(transparent, rgb(0 0 0 / 0.4)),
    0 4px 12px -4px light-dark(transparent, rgb(0 0 0 / 0.5));

  /* 4: hover card, small popover */
  --elev-4:
    0 0 0 1px var(--_ring),
    0 8px 40px light-dark(rgb(0 0 0 / 0.05), rgb(0 0 0 / 0.15)),
    0 12px 32px -16px light-dark(rgb(0 0 0 / 0.059), rgb(0 0 0 / 0.3));

  /* 5: popover, menu */
  --elev-5:
    0 0 0 1px var(--_ring),
    0 12px 60px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.3)),
    0 12px 32px -16px light-dark(rgb(0 0 0 / 0.122), rgb(0 0 0 / 0.5));

  /* 6: dialog */
  --elev-6:
    0 0 0 1px var(--_ring),
    0 12px 60px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.2)),
    0 16px 64px light-dark(rgb(0 0 0 / 0.024), rgb(0 0 0 / 0.4)),
    0 16px 36px -20px light-dark(rgb(0 0 0 / 0.192), rgb(0 0 0 / 0.9));
}

.elev-1 { box-shadow: var(--elev-1); }
.elev-2 { box-shadow: var(--elev-2); }
.elev-3 { box-shadow: var(--elev-3); }
.elev-4 { box-shadow: var(--elev-4); }
.elev-5 { box-shadow: var(--elev-5); }
.elev-6 { box-shadow: var(--elev-6); }

:root {
  color-scheme: light dark;
  /* Hue, saturation, lightness of the shadow ink. Tint toward the surface hue. */
  --shadow-color-light: 220 3% 15%;
  --shadow-color-dark: 220 40% 2%;
  /* The knob. Dark surfaces need far more shadow to be visible. */
  --shadow-strength-light: 1%;
  --shadow-strength-dark: 25%;

  --_s3: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 2%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 2%)));
  --_s4: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 3%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 3%)));
  --_s5: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 4%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 4%)));
  --_s6: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 5%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 5%)));
  --_s8: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 7%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 7%)));
  --_s10: light-dark(hsl(var(--shadow-color-light) / calc(var(--shadow-strength-light) + 9%)), hsl(var(--shadow-color-dark) / calc(var(--shadow-strength-dark) + 9%)));

  --shadow-soft-1: 0 1px 2px -1px var(--_s10);
  --shadow-soft-2:
    0 3px 5px -2px var(--_s4),
    0 7px 14px -5px var(--_s6);
  --shadow-soft-3:
    0 -1px 3px 0 var(--_s3),
    0 1px 2px -5px var(--_s3),
    0 2px 5px -5px var(--_s5),
    0 4px 12px -5px var(--_s6),
    0 12px 15px -5px var(--_s8);
}

.soft-1 { box-shadow: var(--shadow-soft-1); }
.soft-2 { box-shadow: var(--shadow-soft-2); }
.soft-3 { box-shadow: var(--shadow-soft-3); }

/* Example: a warm section tints its shadows warm. */
.section-warm {
  --shadow-color-light: 30 25% 20%;
}

:root { color-scheme: light dark; }

.floating {
  /* Each layer roughly doubles offset and blur: many weak layers avoid the banding of one strong layer. */
  box-shadow:
    0 18px 47px 0 light-dark(rgb(0 0 0 / 0.03), rgb(0 0 0 / 0.15)),
    0 7.5px 19px 0 light-dark(rgb(0 0 0 / 0.02), rgb(0 0 0 / 0.1)),
    0 4px 10.5px 0 light-dark(rgb(0 0 0 / 0.03), rgb(0 0 0 / 0.15)),
    0 2.3px 5.8px 0 light-dark(rgb(0 0 0 / 0.03), rgb(0 0 0 / 0.15)),
    0 1.2px 3.1px 0 light-dark(rgb(0 0 0 / 0.03), rgb(0 0 0 / 0.15)),
    0 0.5px 1.3px 0 light-dark(rgb(0 0 0 / 0.02), rgb(0 0 0 / 0.1)),
    0 0 0 1px light-dark(rgb(0 0 0 / 0.05), rgb(255 255 255 / 0.18));
}

/* Tighter version for small menus and tooltips. */
.floating-sm {
  box-shadow:
    0 17.5px 23.4px 0 light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.2)),
    0 9.4px 12.5px 0 light-dark(rgb(0 0 0 / 0.03), rgb(0 0 0 / 0.15)),
    0 5.25px 7px 0 light-dark(rgb(0 0 0 / 0.02), rgb(0 0 0 / 0.1)),
    0 2.8px 3.7px -2px light-dark(rgb(0 0 0 / 0.01), rgb(0 0 0 / 0.05)),
    0 1.2px 1.5px 0 light-dark(rgb(0 0 0 / 0.01), rgb(0 0 0 / 0.05)),
    0 0 0 1px light-dark(rgb(0 0 0 / 0.05), rgb(255 255 255 / 0.18));
}

@media (forced-colors: active) {
  .floating, .floating-sm { outline: 1px solid CanvasText; }
}

:root {
  color-scheme: light dark;
  --accent: oklch(0.53 0.2 262);
  --accent-fg: oklch(0.99 0 0);
}

/* Quiet: a 1px to 2px tinted contact shadow. */
.tint-shadow {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow: 0 1px 2px 0 color-mix(in oklch, var(--accent) 24%, transparent);
}

/* Louder: a pool of colour under the element. */
.glow-shadow {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow:
    0 10px 15px -3px color-mix(in oklch, var(--accent) 40%, transparent),
    0 4px 6px -4px color-mix(in oklch, var(--accent) 40%, transparent);
}

.tint-shadow:active,
.glow-shadow:active,
.tint-shadow:disabled,
.glow-shadow:disabled {
  box-shadow: none;                     /* pressed or disabled objects sit on the surface */
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
}

.card-layered {
  background: var(--surface);
  border-radius: 20px;
  box-shadow:
    /* dark only: light catches the top inner edge, then a faint inner ring */
    inset 0 1px 0 0 light-dark(transparent, rgb(255 255 255 / 0.03)),
    inset 0 0 0 1px light-dark(transparent, rgb(255 255 255 / 0.03)),
    /* both: outer ring */
    0 0 0 1px light-dark(rgb(17 24 28 / 0.08), rgb(0 0 0 / 0.1)),
    /* light only */
    0 1px 2px -1px light-dark(rgb(17 24 28 / 0.08), transparent),
    0 2px 4px 0 light-dark(rgb(17 24 28 / 0.04), transparent),
    /* dark only: offset and blur double each step */
    0 2px 2px 0 light-dark(transparent, rgb(0 0 0 / 0.1)),
    0 4px 4px 0 light-dark(transparent, rgb(0 0 0 / 0.1)),
    0 8px 8px 0 light-dark(transparent, rgb(0 0 0 / 0.1));
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
}

.bento-card {
  background: var(--surface);
  border-radius: 12px;
  border: 1px solid light-dark(transparent, rgb(255 255 255 / 0.1));
  box-shadow:
    0 0 0 1px light-dark(rgb(0 0 0 / 0.03), transparent),
    0 2px 4px light-dark(rgb(0 0 0 / 0.05), transparent),
    0 12px 24px light-dark(rgb(0 0 0 / 0.05), transparent),
    /* dark only: large inset glow anchored to the bottom edge */
    inset 0 -20px 80px -20px light-dark(transparent, rgb(255 255 255 / 0.12));
}

:root { color-scheme: light dark; }

.shaped-shadow {
  /* Two layers: a tight one for contact, a wide one for ambient. */
  filter:
    drop-shadow(0 3px 3px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.5)))
    drop-shadow(0 12px 12px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.5)));
}

:root {
  color-scheme: light dark;
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --accent: oklch(0.53 0.2 262);
  --accent-fg: oklch(0.99 0 0);
  --ring: color-mix(in oklch, var(--accent) 55%, transparent);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-sizing: border-box;
  height: 36px;
  padding-inline: 14px;
  border: 1px solid transparent;
  border-radius: 8px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.btn-solid {
  --_hover: color-mix(in oklch, var(--accent), light-dark(black, white) 10%);
  --_active: color-mix(in oklch, var(--accent), light-dark(black, white) 18%);
  background-color: var(--accent);
  color: var(--accent-fg);
  transition: background-color 150ms ease-out, scale 150ms ease-out;
}

@media (hover: hover) {
  .btn-solid:hover { background-color: var(--_hover); }
}
.btn-solid:active {
  background-color: var(--_active);
  scale: 0.97;
}

/* Disabled: neutral ink on a neutral wash, not a faded accent. */
.btn-solid:disabled,
.btn-solid[aria-disabled="true"] {
  background-color: light-dark(rgb(0 0 0 / 0.059), rgb(255 255 255 / 0.071));
  color: light-dark(rgb(0 0 0 / 0.267), rgb(255 255 255 / 0.333));
  cursor: not-allowed;
  scale: none;
}

/* Sizes: small 32px, default 36px, large 40px. Less side padding when an icon leads. */
.btn[data-size="sm"] { height: 32px; padding-inline: 12px; gap: 6px; }
.btn[data-size="lg"] { height: 40px; padding-inline: 24px; }
.btn:has(> svg:first-child) { padding-inline-start: 12px; }

@media (prefers-reduced-motion: reduce) {
  .btn-solid:active { scale: none; }
}

:root {
  color-scheme: light dark;
  --accent: oklch(0.53 0.2 262);
  --accent-fg: oklch(0.99 0 0);
  --ring: color-mix(in oklch, var(--accent) 55%, transparent);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-sizing: border-box;
  height: 36px;
  padding-inline: 14px;
  border: 1px solid transparent;
  border-radius: 8px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.btn-glossy {
  position: relative;
  z-index: 0;                           /* own stacking context: the face sits behind the label */
  color: var(--accent-fg);
  background-color: var(--accent);
  /* Rim: the lower half shades toward the bottom edge. */
  background-image:
    linear-gradient(to bottom, transparent 50%, light-dark(rgb(0 0 0 / 0.09), rgb(255 255 255 / 0.106))),
    linear-gradient(to bottom, transparent 50%, var(--accent) 80%);
  box-shadow:
    inset 0 0 0 1px light-dark(rgb(0 0 0 / 0.09), rgb(255 255 255 / 0.1)),   /* outer line */
    inset 0 -2px 1px light-dark(rgb(0 0 0 / 0.059), transparent),             /* light: bottom shade */
    inset 0 4px 2px -2px light-dark(transparent, rgb(255 255 255 / 0.15)),    /* dark: top glow */
    inset 0 1px 1px light-dark(transparent, rgb(255 255 255 / 0.4)),          /* dark: top line */
    inset 0 -1px 1px light-dark(transparent, rgb(0 0 0 / 0.4)),               /* dark: bottom line */
    inset 0 0 0 1px var(--accent),
    inset 0 4px 2px -2px light-dark(rgb(255 255 255 / 0.7), transparent),     /* light: top highlight */
