:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
}

.browser {
  --_r: 12px;
  --_edge: light-dark(rgb(0 0 0 / 0.1), rgb(0 0 0 / 0.8));           /* outer line */
  --_lip: light-dark(rgb(255 255 255 / 0.75), rgb(255 255 255 / 0.12)); /* inner light line */
  --_control: light-dark(rgb(0 0 0 / 0.14), rgb(255 255 255 / 0.2));
  border-radius: var(--_r);
  background: var(--surface);
  overflow: clip;
  box-shadow:
    0 0 0 1px var(--_edge),
    inset 0 0 0 1px var(--_lip),
    0 12px 60px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.3)),
    0 12px 32px -16px light-dark(rgb(0 0 0 / 0.122), rgb(0 0 0 / 0.5));
}

.browser-bar {
  display: grid;
  grid-template-columns: 1fr minmax(0, 20rem) 1fr;
  align-items: center;
  gap: 12px;
  height: 40px;
  padding-inline: 14px;
  background: light-dark(oklch(0.975 0 0), oklch(0.22 0 0));
