}

.browser-url {
  height: 24px;
  border-radius: 6px;
  background: light-dark(rgb(0 0 0 / 0.04), rgb(255 255 255 / 0.06));
  color: var(--fg-muted);
  font-size: 12px;
  line-height: 24px;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
