.logos-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 2rem 3.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--fg-muted);               /* inline SVGs with fill="currentColor" take this */
}
.logos-row svg,
.logos-row img {
  display: block;
  height: 1.5rem;                       /* same height; adjust single logos by eye with --_scale */
  width: auto;
  max-width: 8rem;
