:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
}

.features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 2.5rem 2rem;
  max-width: 64rem;
  margin-inline: auto;
}

.feature {
  display: grid;
  justify-items: start;                 /* left-aligned */
  align-content: start;
  gap: 0.5rem;
}

.feature-icon {
  --_r: 8px;
  position: relative;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  margin-block-end: 0.5rem;
  border: 1px solid var(--hairline);
  border-radius: var(--_r);
  background: var(--surface);
  background-clip: padding-box;
  color: var(--fg);
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.05), 0 1px 2px -1px rgb(0 0 0 / 0.05);
}
.feature-icon::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: calc(var(--_r) - 1px);
  box-shadow:
    0 1px light-dark(oklch(0 0 0 / 0.04), transparent),
    0 -1px light-dark(transparent, oklch(1 0 0 / 0.06));
}
.feature-icon > svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;                    /* 1.5px beside regular text, 2px beside semibold */
}

.feature h3 {
  margin: 0;
  font-size: 1rem;
  line-height: 1.5;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--fg);
}
.feature p {
  margin: 0;
  max-width: 34ch;
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--fg-muted);
  text-wrap: pretty;
}

:root {
  --header-h: 56px;
  --sidebar-w: 16rem;
}

/* Anchor jumps stop below the sticky header. */
html { scroll-padding-top: calc(var(--header-h) + 1rem); }

/* A: documentation shell. */
.shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 2rem;
  align-items: start;
}
@media (min-width: 64rem) {
  .shell { grid-template-columns: var(--sidebar-w) minmax(0, 1fr); }
}

.shell-aside { display: none; }
@media (min-width: 64rem) {
  .shell-aside {
    display: block;
    position: sticky;
    inset-block-start: calc(var(--header-h) + 0.6rem);
    max-height: calc(100svh - var(--header-h) - 2rem);
    overflow-y: auto;
    overscroll-behavior: contain;       /* scrolling the menu never scrolls the page */
    scrollbar-width: thin;
  }
}

/* Compact nav rows with a taller hit area than their visual height. */
.shell-aside a {
  position: relative;
  display: flex;
  align-items: center;
  height: 30px;
  padding-inline: 8px;
  border-radius: 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: inherit;
  text-decoration: none;
}
.shell-aside a::after {
  content: "";
  position: absolute;
  inset: -2px 0;
}
.shell-aside a[aria-current="page"] {
  background: light-dark(rgb(0 0 0 / 0.05), rgb(255 255 255 / 0.07));
}

/* B: marketing section. The heading column sticks, the content column scrolls. */
.sticky-split {
  display: grid;
  gap: 2rem 4rem;
  align-items: start;
}
@media (min-width: 64rem) {
  .sticky-split { grid-template-columns: minmax(0, 2fr) minmax(0, 3fr); }
  .sticky-split > header {
    position: sticky;
    inset-block-start: calc(var(--header-h) + 2rem);
  }
}

:root {
