.plan {
  /* Subgrid: the four rows of every card share the same tracks, so rows align across cards. */
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 4;
  gap: 1.25rem;
  padding: 1.5rem;
  border-radius: 16px;
  background: var(--surface);
