/* The one emphasised plan: accent edge plus a faint halo. Same size as the others. */
.plan[data-featured] {
  box-shadow:
    0 0 0 1px var(--accent),
    0 0 0 4px color-mix(in oklch, var(--accent) 14%, transparent);
}

.plan-name {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0;
