}

/* Lets block-size animate to and from auto where supported. Inherited, so set once. */
:root { interpolate-size: allow-keywords; }

.faq {
  max-width: 48rem;
  border-block-start: 1px solid var(--hairline);
  color: var(--fg);
}
.faq > details { border-block-end: 1px solid var(--hairline); }

.faq summary {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 1rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  list-style: none;                     /* removes the default triangle */
}
.faq summary::-webkit-details-marker { display: none; }
.faq summary:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 6px;
}

/* Chevron drawn with two borders; no icon font or image. */
.faq summary::after {
  content: "";
  flex: none;
  width: 0.5rem;
  height: 0.5rem;
  margin: 0.4rem 0.25rem 0;
  border-inline-end: 1.5px solid var(--fg-muted);
  border-block-end: 1.5px solid var(--fg-muted);
  rotate: 45deg;
  transition: rotate 200ms ease-out, translate 200ms ease-out;
}
.faq details[open] > summary::after {
  rotate: 225deg;
  translate: 0 0.25rem;
}

/* The answer. ::details-content is the built-in wrapper around everything after the summary. */
.faq details::details-content {
  block-size: 0;
  opacity: 0;
  overflow: clip;
  transition:
    block-size 200ms ease-out,
    opacity 200ms ease-out,
    content-visibility 200ms allow-discrete;
}
.faq details[open]::details-content {
  block-size: auto;
  opacity: 1;
}

.faq-answer {
  margin: 0;
  padding-block-end: 1rem;
  max-width: 65ch;
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--fg-muted);
  text-wrap: pretty;
}

/* Two rules, so a browser that does not know ::details-content still applies the second one. */
@media (prefers-reduced-motion: reduce) {
  .faq details::details-content { transition: none; }
  .faq summary::after { transition: none; }
}

