:root {
  /* Section padding: 32px on phones, 48px on tablets, 96px on desktops. The hero gets one more step. */
  --section-y: clamp(2rem, 0.5rem + 6vw, 6rem);
  --section-y-hero: clamp(2rem, 0rem + 9vw, 8rem);
  --gutter: clamp(1rem, 0.5rem + 2vw, 2rem);
  /* Three widths: layout, heading block, running text. */
  --container: 87.5rem;      /* 1400px */
  --measure-wide: 64rem;     /* grids of cards */
  --measure-head: 58rem;     /* centred section headings */
  --measure-text: 42rem;     /* paragraphs */
