  text-wrap: balance;
}
.section-head > p {
  margin: 0 auto;
  max-width: var(--measure-text);
  font-size: clamp(1rem, 0.95rem + 0.3vw, 1.125rem);
  line-height: 1.6;
  text-wrap: pretty;
}

.section-body {
  max-width: var(--measure-wide);
  margin-inline: auto;
}

