}

/* Text sitting on the accent itself (primary buttons, solid badges): invert the highlight. */
.on-accent ::selection,
.on-accent::selection {
  background-color: color-mix(in oklch, var(--accent-fg) 30%, transparent);
}

/* Inputs can take a solid highlight: their text colour is known. */
