}

/* 1. Let the browser draw native controls for the active scheme. */
:root { color-scheme: light dark; }

/* 2. Reserve the scrollbar's space so the layout does not shift when it appears or when scroll is locked. */
html { scrollbar-gutter: stable; }

/* 3. Thin, tinted scrollbars for inner scroll areas. */
.scroller {
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: light-dark(rgb(0 0 0 / 0.28), rgb(255 255 255 / 0.28)) transparent;
}

/* Older WebKit and Chromium: only when the standard properties are missing, because they override these. */
@supports not (scrollbar-color: auto) {
  .scroller::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  .scroller::-webkit-scrollbar-track {
    background: transparent;
  }
  .scroller::-webkit-scrollbar-thumb {
    border: 3px solid transparent;      /* the thumb looks 4px wide but stays 10px to grab */
    border-radius: 999px;
    background-color: light-dark(rgb(0 0 0 / 0.28), rgb(255 255 255 / 0.28));
    background-clip: content-box;
  }
}

/* 4. No scrollbar: horizontal tab lists and chip rows that are also swipeable and keyboard reachable. */
.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* 5. Scrolling inside a panel should not scroll the page behind it. */
.scroller[data-contain] {
  overscroll-behavior: contain;
}

:root {
