  color-scheme: light dark;
  /* Checkboxes, radios, range inputs and progress bars. */
  accent-color: var(--accent);
}

input,
textarea,
[contenteditable] {
  caret-color: var(--accent);
}

/* Native select menus: set both colours explicitly, or Windows dark mode can show dark text on dark. */
select {
  background-color: var(--bg);
  color: var(--fg);
}

/* Force one scheme on a subtree (for example an always-dark code panel). */
.always-dark { color-scheme: dark; }
.always-light { color-scheme: light; }

