/* Pure black or pure white only: a tinted grey picks up the surface colour and reads as a smudge. */
img,
video,
.media-outline {
  outline: 1px solid light-dark(oklch(0 0 0 / 0.1), oklch(1 0 0 / 0.1));
  outline-offset: -1px;                 /* drawn inside, so the image keeps its size */
}

/* Opt out: logos, icons and transparent cut-outs. */
img[data-bare],
img[src$=".svg"] {
  outline: 0;
}

/* Inside out: fix the inner radius, derive the outer. */
.nest {
  --inner-radius: 12px;
  --gap: 8px;
  padding: var(--gap);
  border-radius: calc(var(--inner-radius) + var(--gap));    /* 20px */
}
.nest > .nest-inner {
  border-radius: var(--inner-radius);
}

/* Outside in: fix the outer radius, derive the inner. Never below zero. */
.shell {
  --outer-radius: 16px;
  --gap: 6px;
  padding: var(--gap);
  border-radius: var(--outer-radius);
}
.shell > .shell-inner {
  border-radius: max(0px, calc(var(--outer-radius) - var(--gap)));
}

/* A border counts as a gap: anything drawn inside a 1px border uses the radius minus 1px. */
.bordered {
  --r: 12px;
  border: 1px solid;
  border-radius: var(--r);
}
.bordered > .fill,
.bordered::before {
  border-radius: calc(var(--r) - 1px);
}

/* Taller controls take a slightly larger radius: the base radius grows by 35% of the height increase. */
.control {
  --base-height: 26;
  --base-radius: 6px;
  --height: 34;
  height: calc(var(--height) * 1px);
  border-radius: calc(var(--base-radius) * (1 + (var(--height) / var(--base-height) - 1) * 0.35));
}

/* Smoother corners where supported: the curve starts earlier and has no visible join. */
@supports (corner-shape: squircle) {
  .squircle {
    corner-shape: squircle;
  }
}

/* 1. Text + trailing icon: the icon side gets 2px less padding. */
.btn-icon-end {
  padding-inline: 16px 14px;
}
/* Text + leading icon: same rule, mirrored. */
.btn-icon-start {
  padding-inline: 14px 16px;
}

/* 2. Or pull the icon outward so normal padding can stay. */
.btn > svg {
  flex-shrink: 0;
  margin-inline: -2px;
}

/* 3. Triangles are heavier on their flat side: nudge play icons toward the point. */
.play-button > svg {
  margin-inline-start: 2px;
}

/* 4. Inline icons: text-sized, dropped slightly so they sit on the baseline rather than float. */
.icon-inline {
  width: 1em;
  height: 1em;
  vertical-align: -0.125em;
  flex-shrink: 0;
}

/* 5. Stroke weight follows text weight (24px grid). */
.icon { fill: none; stroke: currentColor; stroke-width: 1.5; }
.semibold .icon, strong .icon { stroke-width: 2; }

/* 6. Small controls beside taller text lines: move them down to the first line's centre. */
.checkbox-in-row { translate: 0 2px; }
.chevron-in-trigger { translate: 0 2px; }

:root {
