a {
  color: var(--accent-text);
  text-decoration-line: underline;
  text-decoration-style: solid;
  /* 1px at body sizes, growing with large text, capped at 2px. */
  text-decoration-thickness: min(2px, max(1px, 0.05em));
  /* A fixed 2px gap plus a little that scales with the font. */
  text-underline-offset: calc(0.025em + 2px);
  /* Quieter than the text. */
  text-decoration-color: color-mix(in oklab, currentColor 40%, transparent);
  transition: text-decoration-color 150ms ease-out;
}

@media (hover: hover) {
  a:hover { text-decoration-color: currentColor; }
}

a:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 0.2em;
  text-decoration-line: none;           /* ring replaces underline while focused */
}

/* Navigation and UI links: underline on hover only. Body-text links keep it always. */
nav a,
.link-quiet {
  color: inherit;
  text-decoration-line: none;
}
@media (hover: hover) {
  nav a:hover,
  .link-quiet:hover {
    text-decoration-line: underline;
    text-underline-offset: 4px;
  }
}

:root {
  color-scheme: light dark;
  --accent: oklch(0.53 0.2 262);
}

/* A. Centre a target of at least 44px on a smaller control. */
.hit-44 {
  position: relative;
}
.hit-44::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  width: max(100%, 44px);
  height: max(100%, 44px);
  translate: -50% -50%;
}

/* B. Only for fingers: grow the target by 8px on every side on coarse pointers. */
@media (pointer: coarse) {
  .hit-coarse {
    position: relative;
  }
  .hit-coarse::after {
    content: "";
    position: absolute;
    inset: -8px;
  }
}

/* C. Dense vertical lists: rows look 30px tall but accept clicks in the gaps between them. */
.hit-row {
  position: relative;
}
.hit-row::after {
  content: "";
  position: absolute;
  inset: -4px 0;
}

/* D. Tap behaviour for every control. */
:where(a, button, [role="button"], input, select, summary, label) {
  -webkit-tap-highlight-color: transparent;   /* remove the grey flash; replaced below */
  touch-action: manipulation;                  /* no double-tap zoom delay */
}
@media (pointer: coarse) {
  :where(button, [role="button"]):active {
    outline: 0.5em solid color-mix(in oklch, var(--accent) 20%, transparent);
    outline-offset: 0;
  }
}

/* Trim the line box to the top of capital letters and to the alphabetic baseline. */
.label-trim {
  text-box: trim-both cap alphabetic;
}

/* Buttons and badges: equal padding now gives equal visual space. */
@supports (text-box: trim-both cap alphabetic) {
  .btn-trim {
    display: inline-flex;
    align-items: center;
    height: auto;
    padding: 11px 14px;                 /* same number top and bottom, and it looks the same */
  }
  .btn-trim > .label-trim {
    line-height: 1;
  }
}

/* Headings next to media: the cap height meets the image's top edge. */
.media-row {
  display: grid;
  grid-template-columns: 96px 1fr;
  gap: 16px;
  align-items: start;
}
.media-row > h3 {
  margin: 0;
  text-box: trim-start cap alphabetic;
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
  --accent: oklch(0.53 0.2 262);
  --danger: light-dark(oklch(0.55 0.21 27), oklch(0.68 0.19 25));
}

/* The wrapper draws the box, so it can carry icons, buttons and edge shading. */
.field {
  --_r: 8px;
  --_edge: light-dark(oklch(0 0 0 / 0.1), oklch(1 0 0 / 0.08));
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding-inline: 11px;                 /* 12px minus the border */
  border: 1px solid var(--_edge);
  border-radius: var(--_r);
  background-color: light-dark(var(--surface), oklch(1 0 0 / 0.026));
  background-clip: padding-box;
  color: var(--fg);
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  outline: 2px solid transparent;       /* shows in forced-colours mode */
  outline-offset: 1px;
  transition: border-color 150ms ease-out, box-shadow 150ms ease-out;
}
/* Bottom edge shade (light) or top edge highlight (dark), following the radius. */
.field::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: calc(var(--_r) - 1px);
  pointer-events: none;
  box-shadow:
    0 1px light-dark(oklch(0 0 0 / 0.04), transparent),
    0 -1px light-dark(transparent, oklch(1 0 0 / 0.06));
}

.field > input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 16px;                      /* 16px on small screens stops iOS zooming on focus */
  outline: none;
}
@media (min-width: 40rem) {
  .field > input { font-size: 14px; }
}
.field > input::placeholder {
  color: color-mix(in oklch, var(--fg-muted) 72%, transparent);
}
.field > svg {
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--fg-muted);
}

/* Hover */
@media (hover: hover) {
  .field:hover { --_edge: light-dark(oklch(0 0 0 / 0.18), oklch(1 0 0 / 0.16)); }
}

/* Focus */
.field:has(> input:focus-visible) {
  border-color: color-mix(in oklch, var(--accent) 80%, transparent);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--accent) 24%, transparent);
}
.field:has(> input:focus-visible)::before { box-shadow: none; }

/* Error */
.field:has(> input[aria-invalid="true"]) {
  border-color: color-mix(in oklch, var(--danger) 36%, transparent);
}
.field:has(> input[aria-invalid="true"]:focus-visible) {
  border-color: color-mix(in oklch, var(--danger) 64%, transparent);
  box-shadow: 0 0 0 3px light-dark(
    color-mix(in oklch, var(--danger) 16%, transparent),
    color-mix(in oklch, var(--danger) 24%, transparent)
  );
}
.field-error {
  margin: 6px 0 0;
  font-size: 13px;
  line-height: 1.4;
  color: var(--danger);
}

/* Disabled */
.field:has(> input:disabled) {
  opacity: 0.64;
  box-shadow: none;
  cursor: not-allowed;
}
.field:has(> input:disabled)::before { box-shadow: none; }

/* Housekeeping */
.field > input::-webkit-search-cancel-button { appearance: none; }
.field > input[type="number"] { -moz-appearance: textfield; appearance: textfield; }
.field > input::-webkit-inner-spin-button { appearance: none; }

:root {
