}

.badge {
  --_c: oklch(0.55 0.02 260);           /* the tone; neutral by default */
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 6px;
  background-color: light-dark(
    color-mix(in oklch, var(--_c) 8%, transparent),
    color-mix(in oklch, var(--_c) 16%, transparent)
  );
  /* Text: the tone pulled toward black in light mode and toward white in dark mode. */
  color: light-dark(color-mix(in oklch, var(--_c) 60%, black), color-mix(in oklch, var(--_c) 55%, white));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--_c) 24%, transparent);
  font-size: 12px;
  line-height: 16px;
  font-weight: 500;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.badge[data-tone="success"] { --_c: oklch(0.62 0.15 155); }
.badge[data-tone="warning"] { --_c: oklch(0.7 0.15 75); }
.badge[data-tone="danger"]  { --_c: oklch(0.6 0.2 27); }
.badge[data-tone="info"]    { --_c: oklch(0.6 0.17 250); }

