.badge[data-shape="pill"] { border-radius: 999px; }

/* Status dot instead of colouring the whole badge. */
.badge[data-dot]::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--_c);
}

/* Solid count badge. */
.badge[data-variant="solid"] {
  background-color: var(--fg);
  color: light-dark(white, black);
  box-shadow: none;
}

/* Outline: ring only. */
.badge[data-variant="outline"] {
  background-color: transparent;
  color: var(--fg);
  box-shadow: inset 0 0 0 1px light-dark(oklch(0 0 0 / 0.12), oklch(1 0 0 / 0.16));
}

:root {
