.tabs {
  position: relative;
  display: flex;
  gap: 4px;
  box-shadow: inset 0 -1px 0 0 var(--hairline);   /* the track */
  overflow-x: auto;
  scrollbar-width: none;
  white-space: nowrap;
}
.tabs::-webkit-scrollbar { display: none; }

.tab {
  position: relative;
  flex: none;
  height: 40px;
  padding-inline: 12px;
  border: 0;
  background: none;
  color: var(--fg-muted);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
  transition: color 150ms ease-out;
