  letter-spacing: -0.01em;
}
.tab:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
  border-radius: 6px;
}

/* Reserve the width of the bold label, so selecting a tab never shifts its neighbours. */
.tab::after {
  content: attr(data-label);
  display: block;
  height: 0;
  overflow: hidden;
  visibility: hidden;
  font-weight: 500;
  letter-spacing: -0.01em;
