  .tabs::after {
    content: "";
    position: absolute;
    position-anchor: --active-tab;
    left: anchor(left);
    right: anchor(right);
    bottom: 0;
    height: 2px;
    background: var(--accent);
  }
  @media (prefers-reduced-motion: no-preference) {
