  --_r: 8px;
  position: relative;
  display: inline-grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  align-items: stretch;
  height: 32px;
  min-width: max-content;
  border-radius: var(--_r);
  color: var(--fg);
