.segmented-thumb {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: -1;
  width: calc(100% / var(--n));
  pointer-events: none;
  transition: transform 100ms cubic-bezier(0.445, 0.05, 0.55, 0.95);
