  content: "";
  position: absolute;
  inset: 1px;
  border-radius: max(0.5px, calc(var(--_r) - 1px));
  background-color: light-dark(white, rgb(255 255 255 / 0.071));
  box-shadow:
    0 0 0 1px light-dark(rgb(0 0 0 / 0.059), rgb(255 255 255 / 0.106)),
