.segmented:has(> label:nth-child(2) input:checked) > .segmented-thumb { transform: translateX(100%); }
.segmented:has(> label:nth-child(3) input:checked) > .segmented-thumb { transform: translateX(200%); }
.segmented:has(> label:nth-child(4) input:checked) > .segmented-thumb { transform: translateX(300%); }
