.has-tip {
  position: relative;
}

.tip {
  position: absolute;
  inset-block-end: calc(100% + 6px);
  inset-inline-start: 50%;
  z-index: 50;
  width: max-content;
  max-width: 15rem;
  padding: 4px 8px;
  border-radius: 6px;
  /* Inverted: the text colour becomes the fill. */
  background: var(--fg);
  color: var(--bg);
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  text-align: center;
  text-wrap: balance;
  pointer-events: none;
  user-select: none;
  /* Hidden state: 4px toward the trigger, 97% size, transparent. */
  opacity: 0;
  translate: -50% 4px;
  scale: 0.97;
  transform-origin: 50% 100%;           /* grows from the edge nearest the trigger */
  transition:
    opacity 100ms cubic-bezier(0.16, 1, 0.3, 1),
    translate 100ms cubic-bezier(0.16, 1, 0.3, 1),
    scale 100ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Show: slower in than out, with a hover delay. */
@media (hover: hover) {
  .has-tip:hover > .tip {
    opacity: 1;
    translate: -50% 0;
    scale: 1;
    transition-duration: 140ms;
    transition-delay: 200ms;
  }
}
/* Keyboard focus: no delay. */
.has-tip:focus-visible > .tip {
  opacity: 1;
  translate: -50% 0;
  scale: 1;
  transition-duration: 140ms;
  transition-delay: 0ms;
