/* Keyboard hint inside a tooltip. */
.tip > kbd {
  margin-inline-start: 6px;
  padding: 0 4px;
  border-radius: 4px;
  background: color-mix(in oklch, var(--bg) 20%, transparent);
  font: inherit;
}

@media (prefers-reduced-motion: reduce) {
  .tip { translate: -50% 0; scale: 1; }
}

:root {
  color-scheme: light dark;
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
}

/* Lock page scroll while a modal dialog is open; scrollbar-gutter stops the page from shifting. */
html { scrollbar-gutter: stable; }
html:has(dialog.modal[open]) { overflow: hidden; }

dialog.modal {
  box-sizing: border-box;
  width: min(100% - 2rem, 32rem);
  max-height: min(100% - 2rem, 40rem);
  margin: auto;
  padding: 24px;
  border: 0;
  border-radius: 16px;
  background: light-dark(oklch(1 0 0), oklch(0.21 0 0));
  color: var(--fg);
  overflow: auto;
  overscroll-behavior: contain;
  box-shadow:
    0 0 0 1px light-dark(rgb(0 0 0 / 0.059), rgb(255 255 255 / 0.173)),
    0 12px 60px light-dark(rgb(0 0 0 / 0.15), rgb(0 0 0 / 0.2)),
    0 16px 64px light-dark(rgb(0 0 0 / 0.024), rgb(0 0 0 / 0.4)),
    0 16px 36px -20px light-dark(rgb(0 0 0 / 0.192), rgb(0 0 0 / 0.9));

  /* Closed state (also the end of the exit). */
  opacity: 0;
  translate: 0 5px;
  scale: 0.99;
  transition:
    opacity 100ms cubic-bezier(0.16, 1, 0.3, 1),
    translate 100ms cubic-bezier(0.16, 1, 0.3, 1),
    scale 100ms cubic-bezier(0.16, 1, 0.3, 1),
    overlay 100ms allow-discrete,
    display 100ms allow-discrete;
}
dialog.modal[open] {
  opacity: 1;
  translate: 0 0;
  scale: 1;
  transition-duration: 200ms;           /* enter is slower than exit */
}
@starting-style {
  dialog.modal[open] {
    opacity: 0;
    translate: 0 5px;
    scale: 0.97;
  }
}

dialog.modal::backdrop {
  background-color: transparent;
  -webkit-backdrop-filter: blur(0);
  backdrop-filter: blur(0);
  transition:
    background-color 160ms cubic-bezier(0.16, 1, 0.3, 1),
    backdrop-filter 160ms cubic-bezier(0.16, 1, 0.3, 1),
    overlay 160ms allow-discrete,
    display 160ms allow-discrete;
}
dialog.modal[open]::backdrop {
  background-color: light-dark(rgb(0 0 0 / 0.4), rgb(0 0 0 / 0.6));
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
  transition-duration: 200ms;
}
@starting-style {
  dialog.modal[open]::backdrop {
    background-color: transparent;
    -webkit-backdrop-filter: blur(0);
    backdrop-filter: blur(0);
  }
}

.modal-title { margin: 0; font-size: 18px; line-height: 1; font-weight: 600; }
.modal-description { margin: 8px 0 0; font-size: 14px; line-height: 1.5; color: var(--fg-muted); }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-block-start: 24px; }

/* Small screens: a bottom sheet. */
@media (max-width: 40rem) {
  dialog.modal {
    width: 100%;
    max-width: none;
    max-height: 85dvh;
    margin: auto 0 0;
    padding-block-end: max(24px, env(safe-area-inset-bottom));
    border-radius: 16px 16px 0 0;
    translate: 0 100%;
    scale: 1;
    opacity: 1;
    transition:
      translate 500ms cubic-bezier(0.32, 0.72, 0, 1),
      overlay 500ms allow-discrete,
      display 500ms allow-discrete;
  }
  dialog.modal[open] {
    translate: 0 0;
    transition-duration: 500ms;
  }
  @starting-style {
    dialog.modal[open] {
      opacity: 1;
      translate: 0 100%;
      scale: 1;
    }
  }
  .modal-actions { flex-direction: column-reverse; }
  .modal-actions > * { width: 100%; }

  .sheet-handle {
    display: block;
    width: 32px;
    height: 5px;
    margin: -8px auto 16px;
    border-radius: 1rem;
    background: light-dark(#e2e2e4, #3a3a3c);
    opacity: 0.7;
  }
}
@media (min-width: 40.01rem) {
  .sheet-handle { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  dialog.modal,
  dialog.modal[open] { translate: none; scale: none; transition-duration: 100ms; }
}

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
  --accent: oklch(0.53 0.2 262);
  --ring: color-mix(in oklch, var(--accent) 55%, transparent);
}

.table-wrap {
  max-height: 24rem;
  overflow: auto;
  border: 1px solid var(--hairline);
  border-radius: 12px;
  background: var(--surface);
  background-clip: padding-box;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 20px;
  color: var(--fg);
  font-variant-numeric: tabular-nums;
}

.table th {
  position: sticky;
  inset-block-start: 0;
  z-index: 1;
  height: 40px;
  padding-inline: 12px;
  text-align: start;
  font-weight: 500;
  color: var(--fg-muted);
  white-space: nowrap;
  background: var(--surface);           /* opaque, or rows show through the pinned header */
  /* border-collapse drops borders on sticky cells, so the divider is an inset shadow. */
  box-shadow: inset 0 -1px 0 var(--hairline);
}

.table td {
  padding: 10px 12px;
  vertical-align: middle;
  border-block-end: 1px solid var(--hairline);
}
.table tbody tr:last-child td { border-block-end: 0; }

.table [data-type="number"] { text-align: end; }

/* Hover: colour only, no transition on entry so it tracks the pointer. */
@media (hover: hover) {
  .table tbody tr:hover td {
    background-color: light-dark(rgb(0 0 0 / 0.02), rgb(255 255 255 / 0.02));
  }
}

/* Selected */
.table tbody tr[aria-selected="true"] td {
  background-color: light-dark(rgb(0 0 0 / 0.04), rgb(255 255 255 / 0.04));
}

/* Zebra: use instead of row dividers in very wide tables. */
.table[data-zebra] td { border-block-end: 0; }
.table[data-zebra] tbody tr:nth-child(even) td {
  background-color: light-dark(rgb(0 0 0 / 0.024), rgb(255 255 255 / 0.035));
}

/* The scroll container is focusable so it can be scrolled by keyboard. */
.table-wrap:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* Rows that act as links: inset focus ring. Outline, not box-shadow: shadows on table rows are unreliable in Safari. */
.table tbody tr[tabindex] {
  outline: 2px solid transparent;
  outline-offset: -2px;
  cursor: pointer;
}
.table tbody tr[tabindex]:focus-visible { outline-color: var(--ring); }

:root {
  color-scheme: light dark;
  --surface: light-dark(oklch(1 0 0), oklch(0.19 0 0));
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
  --hairline: light-dark(oklch(0 0 0 / 0.08), oklch(1 0 0 / 0.1));
}

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-width: 0;
  padding: clamp(1.5rem, 6vw, 3rem);
  border: 1px dashed light-dark(oklch(0 0 0 / 0.16), oklch(1 0 0 / 0.18));
  border-radius: 12px;
  text-align: center;
  text-wrap: balance;
  color: var(--fg);
}

.empty-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  max-width: 24rem;
  isolation: isolate;                   /* keeps the fanned tiles (z-index: -1) above the page background */
}

/* Icon tile, with two faint tiles fanned behind it. */
.empty-icon {
  --_r: 8px;
  position: relative;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  margin-block-end: 8px;
  border: 1px solid var(--hairline);
  border-radius: var(--_r);
  background: var(--surface);
  background-clip: padding-box;
  box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.05), 0 1px 2px -1px rgb(0 0 0 / 0.05);
}
.empty-icon::before,
.empty-icon::after {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  border: 1px solid var(--hairline);
  border-radius: var(--_r);
  background: var(--surface);
  scale: 0.84;
}
.empty-icon::before { transform-origin: 0% 100%; rotate: -10deg; translate: -2px 0; }
.empty-icon::after { transform-origin: 100% 100%; rotate: 10deg; translate: 2px 0; }
.empty-icon > svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
}

.empty-title {
  margin: 0;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 500;
  letter-spacing: -0.025em;
}
.empty-description {
  margin: 0;
  font-size: 14px;
  line-height: 1.625;
  color: var(--fg-muted);
}
.empty-description > a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.empty-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

:root {
  color-scheme: light dark;
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
}

.toaster {
  --width: 356px;
  --gap: 14px;
  position: fixed;
  inset-block-end: 24px;
  inset-inline-end: 24px;
  z-index: 100;
  display: grid;
  width: min(var(--width), 100vw - 32px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.toast {
  --i: 0;                               /* 0 = newest (front) */
  grid-area: 1 / 1;                     /* all toasts share one cell, so they all take the height of the tallest */
  z-index: calc(10 - var(--i));
  display: flex;
  align-items: center;
  gap: 6px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid light-dark(hsl(0 0% 93%), hsl(0 0% 20%));
  border-radius: 8px;
  background: light-dark(#fff, #000);
  color: light-dark(hsl(0 0% 9%), hsl(0 0% 99%));
  font-size: 13px;
  box-shadow: 0 4px 12px rgb(0 0 0 / 0.1);
  /* Collapsed: each older toast is lifted by one gap and scaled down 5%. */
  transform: translateY(calc(var(--i) * var(--gap) * -1)) scale(calc(1 - var(--i) * 0.05));
  transform-origin: 50% 100%;
  transition: transform 400ms ease, opacity 400ms ease, box-shadow 200ms ease;
}
.toast:nth-last-child(1) { --i: 0; }
.toast:nth-last-child(2) { --i: 1; }
.toast:nth-last-child(3) { --i: 2; }
.toast:nth-last-child(n + 4) { --i: 3; opacity: 0; pointer-events: none; }   /* three visible */

/* Behind the front toast, hide the content so only the card edge peeks out. */
.toast:not(:nth-last-child(1)) > * {
  opacity: 0;
  transition: opacity 400ms ease;
}

/* Expanded on hover or keyboard focus: a plain list with gaps. Every toast has the height of the tallest one. */
.toaster:hover > .toast,
.toaster:focus-within > .toast {
  transform: translateY(calc(var(--i) * (-100% - var(--gap))));
}
.toaster:hover > .toast > *,
.toaster:focus-within > .toast > * {
  opacity: 1;
}

/* Entrance: slide up from below its resting place. */
@starting-style {
  .toast {
    opacity: 0;
    transform: translateY(100%);
  }
}

.toast-title { font-weight: 500; line-height: 1.5; }
.toast-description { font-weight: 400; line-height: 1.4; color: var(--fg-muted); }
.toast-action {
  margin-inline-start: auto;
  height: 24px;
  padding-inline: 8px;
  border: 0;
  border-radius: 4px;
  background: light-dark(hsl(0 0% 9%), hsl(0 0% 99%));
  color: light-dark(#fff, #000);
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
.toast:focus-visible,
.toast-action:focus-visible {
  outline: none;
  box-shadow: 0 4px 12px rgb(0 0 0 / 0.1), 0 0 0 2px light-dark(rgb(0 0 0 / 0.2), rgb(255 255 255 / 0.3));
}

@media (prefers-reduced-motion: reduce) {
  .toast,
  .toast > * { transition: none; }
}

:root {
  color-scheme: light dark;
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
  --accent: oklch(0.53 0.2 262);
}

.cmd {
  --_fill: light-dark(hsl(0 0% 99%), hsl(0 0% 11%));
  --_line: light-dark(hsl(0 0% 88.7%), hsl(0 0% 20.5%));
  --_selected: light-dark(hsl(0 0% 93%), hsl(0 0% 15.8%));
  width: min(640px, 100% - 2rem);
  padding: 8px 0;
  border: 1px solid light-dark(var(--_line), transparent);
  border-radius: 12px;
  background: var(--_fill);
  color: var(--fg);
  box-shadow:
    0 16px 70px rgb(0 0 0 / 0.2),
    /* dark: a ring and a lit top edge instead of a border */
    0 0 0 1px light-dark(transparent, var(--_line)),
    inset 0 1px 0 0 light-dark(transparent, rgb(255 255 255 / 0.08));
  font-size: 14px;
}

.cmd-input {
  width: 100%;
  box-sizing: border-box;
  padding: 8px 16px 16px;
  border: 0;
  border-block-end: 1px solid var(--_line);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 16px;
  caret-color: var(--accent);
  outline: none;
}
.cmd-input::placeholder { color: light-dark(hsl(0 0% 56.1%), hsl(0 0% 43.9%)); }

.cmd-list {
  max-height: 393px;
  margin: 0;
  padding: 8px 8px 0;
  overflow: auto;
  overscroll-behavior: contain;
  scroll-padding-block: 8px 40px;
  list-style: none;
}

.cmd-heading {
  padding: 8px 8px 4px;
  font-size: 12px;
  color: var(--fg-muted);
  user-select: none;
}

.cmd-item {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  padding-inline: 8px;
  border-radius: 8px;
  cursor: pointer;
  user-select: none;
  content-visibility: auto;             /* skip rendering rows that are scrolled out of view */
}
.cmd-item + .cmd-item { margin-block-start: 4px; }
.cmd-item > svg { width: 18px; height: 18px; flex: none; color: var(--fg-muted); }
.cmd-item[aria-selected="true"] { background: var(--_selected); }
.cmd-item[aria-disabled="true"] { color: var(--fg-muted); cursor: not-allowed; }

.cmd-meta {
  margin-inline-start: auto;
  display: flex;
  gap: 4px;
  font-size: 13px;
  color: var(--fg-muted);
}
.cmd-meta > kbd {
  display: grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding-inline: 4px;
  border-radius: 4px;
  background: light-dark(hsl(0 0% 95.1%), hsl(0 0% 13.6%));
  font: inherit;
  font-size: 12px;
}

/* Variant: a 3px accent bar marks the selection, rows are square and taller. */
.cmd[data-style="bar"] .cmd-list { padding-inline: 0; }
.cmd[data-style="bar"] .cmd-item {
  position: relative;
  height: 48px;
  padding-inline: 16px;
  border-radius: 0;
  gap: 12px;
}
.cmd[data-style="bar"] .cmd-item[aria-selected="true"]::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  width: 3px;
  background: var(--accent);
}

/* Entrance */
@media (prefers-reduced-motion: no-preference) {
  .cmd { animation: cmd-in 150ms cubic-bezier(0.16, 1, 0.3, 1) backwards; }
}
@keyframes cmd-in {
  from {
    opacity: 0;
    scale: 0.96;
  }
}

:root {
  color-scheme: light dark;
  --fg: light-dark(oklch(0.2 0 0), oklch(0.96 0 0));
  --fg-muted: light-dark(oklch(0.45 0 0), oklch(0.72 0 0));
}

.kbd {
  position: relative;
  inset-block-start: -0.03em;           /* optical: sits slightly above the baseline box */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
  min-width: 1.75em;
  height: fit-content;
  padding: 0 0.5em 0.05em;
  border-radius: 0.35em;
  background-color: light-dark(#fcfcfc, #111111);
  color: var(--fg);
  font-family: inherit;
  font-size: 0.75em;
  font-weight: 400;
  line-height: 1.7em;
  word-spacing: -0.1em;
  white-space: nowrap;
  vertical-align: text-top;
  user-select: none;
  box-shadow:
    inset 0 -0.05em 0.5em light-dark(rgb(0 0 0 / 0.024), rgb(255 255 255 / 0.071)),
    inset 0 0.05em light-dark(rgb(255 255 255 / 0.95), rgb(255 255 255 / 0.686)),   /* top highlight */
    inset 0 0.25em 0.5em light-dark(rgb(0 0 0 / 0.024), rgb(255 255 255 / 0.035)),
    inset 0 -0.05em light-dark(rgb(0 0 0 / 0.149), transparent),                    /* light: bottom edge */
    inset 0 -0.1em light-dark(transparent, rgb(0 0 0 / 0.9)),                       /* dark: bottom edge */
    0 0 0 0.05em light-dark(rgb(0 0 0 / 0.122), transparent),                       /* light: outline */
    0 0 0 0.075em light-dark(transparent, rgb(255 255 255 / 0.231)),                /* dark: outline */
    0 0.08em 0.17em light-dark(rgb(0 0 0 / 0.192), rgb(0 0 0 / 0.95));              /* drop */
}

/* Flat variant for dense menus. */
.kbd[data-variant="flat"] {
  inset-block-start: 0;
  min-width: 20px;
  height: 20px;
  padding: 0 4px;
  border-radius: 4px;
  background-color: light-dark(rgb(0 0 0 / 0.04), rgb(255 255 255 / 0.06));
  color: var(--fg-muted);
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
  box-shadow: none;
}
